package za.co.lepetse.admin;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.core.type.TypeReference;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.math.*;
import java.security.Principal;
import java.time.*;
import java.util.*;
import org.springframework.http.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;

/** Supplier approval and customer quotation are separate, versioned decisions. */
@RestController @RequestMapping("/api/admin/rfqs/{rfq}/pricing")
public class AdminPricingWorkflow {
 private final JdbcTemplate db; private final ObjectMapper json;
 public AdminPricingWorkflow(JdbcTemplate db,ObjectMapper json){this.db=db;this.json=json;}
 public record Source(@Min(1) long itemId, Long productId, Long supplierLineId, @Min(1) @Max(999999) Integer quantity,
   @NotNull @DecimalMin("0.0001") @DecimalMax("1000000") BigDecimal conversion,
   @DecimalMin("0") @DecimalMax("9999999999") BigDecimal expectedPackPrice, boolean alternativeConfirmed){}
 public record Sourcing(@Min(0) long version,@NotNull @Size(max=250) List<@NotNull @Valid Source> lines){}
 public record Approval(@Min(1) long version){}
 public record Reason(@NotBlank @Size(max=2000) String reason){}
 public record Item(@NotBlank @Size(max=4000) String description,@Min(1) @Max(999999) int quantity,@NotBlank @Size(max=100) String unit,Long productId){}
 public record SellLine(@Min(1) long itemId,@NotBlank @Size(max=4000) String description,
   @NotNull @DecimalMin("0") @DecimalMax("10000") BigDecimal markup,
   @NotNull @DecimalMin("0") @DecimalMax("9999999999") @Digits(integer=10,fraction=2) BigDecimal sellingPrice){}
 public record QuoteDraft(@Min(0) long version,@Min(1) long approvalVersion,
   @NotEmpty @Size(max=250) List<@NotNull @Valid SellLine> lines,
   @NotNull @DecimalMin("0") @DecimalMax("9999999999") @Digits(integer=10,fraction=2) BigDecimal transport,
   @NotNull @DecimalMin("0") @DecimalMax("1") BigDecimal vatRate,
   @NotNull LocalDate validUntil,@NotBlank @Size(max=5000) String terms){}
 public record Finalise(@Min(1) long version,@NotNull UUID submissionKey){}
 public record Sent(@NotBlank @Email @Size(max=254) String recipient){}
 private ResponseStatusException bad(String s){return new ResponseStatusException(HttpStatus.BAD_REQUEST,s);}
 private ResponseStatusException conflict(String s){return new ResponseStatusException(HttpStatus.CONFLICT,s);}
 private String encode(Object o){try{return json.writeValueAsString(o);}catch(Exception e){throw new IllegalStateException(e);}}
 private Map<String,Object> decode(Object o){try{return json.readValue(o.toString(),new TypeReference<LinkedHashMap<String,Object>>(){});}catch(Exception e){throw new IllegalStateException(e);}}
 private <T>T read(Object o,Class<T> type){try{return json.readValue(o.toString(),type);}catch(Exception e){throw new IllegalStateException(e);}}
 private long number(Object o){return ((Number)o).longValue();}
 private BigDecimal decimal(Object o){return new BigDecimal(o.toString());}
 private Map<String,Object> request(long id,boolean lock){var rows=db.queryForList("select * from rfq where id=? and status<>'draft'"+(lock?" for update":""),id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Request not found.");return rows.getFirst();}
 private Map<String,Object> state(long rfq){var rows=db.queryForList("select * from rfq_pricing_work where rfq_id=?",rfq);if(rows.isEmpty())throw conflict("Save sourcing first.");return rows.getFirst();}
 private void sourcingOnly(Map<String,Object> r){if(!Set.of("submitted","in_review").contains(r.get("status")))throw conflict("Return this request to sourcing before changing approved products or costs.");}
 private void approvedOnly(Map<String,Object> r){if(!Set.of("approved","quoted").contains(r.get("status")))throw conflict("Approve supplier sourcing before preparing the customer quotation.");}
 private List<Map<String,Object>> items(long rfq){return db.queryForList("select * from rfq_item where rfq_id=? order by display_order,id",rfq);}
 private void event(long id,Principal p,String type,String text){db.update("insert into rfq_pricing_event(rfq_id,actor,event_type,summary) values (?,?,?,?)",id,p.getName(),type,text);}
 private void status(long id,String from,String to,Principal p){db.update("update rfq set status=? where id=?",to,id);db.update("insert into rfq_activity(rfq_id,actor_username,previous_status,new_status) values (?,?,?,?)",id,p.getName(),from,to);}
 @GetMapping @Transactional(readOnly=true,isolation=org.springframework.transaction.annotation.Isolation.REPEATABLE_READ)
 Map<String,Object> get(@PathVariable long rfq){request(rfq,false);var rows=db.queryForList("select * from rfq_pricing_work where rfq_id=?",rfq);var result=new LinkedHashMap<String,Object>();if(!rows.isEmpty()){result.putAll(rows.getFirst());for(String key:List.of("sourcing_draft","approval","quote_draft"))if(result.get(key)!=null)result.put(key,decode(result.get(key)));}else{result.put("sourcing_version",0);result.put("quote_version",0);result.put("approval_version",0);result.put("sourcing_draft",Map.of("lines",List.of()));}result.put("quotations",db.queryForList("select id,reference,status,valid_until,approval_version,draft_version,emailed_at,sent_to from quotation where rfq_id=? order by revision desc",rfq));result.put("history",db.queryForList("select actor,event_type,summary,created_at from rfq_pricing_event where rfq_id=? order by id desc",rfq));result.put("emailConnected",false);return result;}
 private Map<String,Object> offer(Source l,Map<String,Object> request,boolean approve){
  if(l.productId()!=null&&db.queryForObject("select count(*) from product where id=? and active",Integer.class,l.productId())!=1)throw bad("Choose an active catalogue product.");
  if(l.supplierLineId()==null){if(approve)throw bad("Choose a supplier offer for every item.");return Map.of();}
  var rows=db.queryForList("select l.*,q.reference,q.valid_until,s.name supplier from supplier_quote_line l join supplier_quote q on q.id=l.quote_id join supplier s on s.id=q.supplier_id where l.id=? for share of l,q",l.supplierLineId());if(rows.isEmpty())throw bad("Supplier offer not found.");var o=rows.getFirst();if(l.productId()==null||o.get("product_id")==null||number(o.get("product_id"))!=l.productId())throw bad("The supplier offer must match the chosen product.");
  if(approve){if(o.get("valid_until")!=null&&((java.sql.Date)o.get("valid_until")).toLocalDate().isBefore(LocalDate.now()))throw bad("A supplier offer has expired. Return to sourcing and approve a current offer.");if(l.expectedPackPrice()==null||l.expectedPackPrice().compareTo(decimal(o.get("pack_price_ex_vat")))!=0)throw conflict("A supplier price changed. Review the current offer before approval.");if(o.get("match_type").equals("alternative")&&(!l.alternativeConfirmed()||!Boolean.TRUE.equals(request.get("alternatives_allowed"))))throw bad("An alternative needs customer permission and your review.");}return o;
 }
 @PostMapping("/sourcing") @Transactional
 Map<String,Object> saveSource(@PathVariable long rfq,@Valid @RequestBody Sourcing body,Principal p){var r=request(rfq,true);sourcingOnly(r);var rows=db.queryForList("select sourcing_version from rfq_pricing_work where rfq_id=?",rfq);long version=rows.isEmpty()?0:number(rows.getFirst().get("sourcing_version"));if(version!=body.version())throw conflict("Sourcing changed in another session. Reload before saving.");var allowed=new HashSet<>(db.queryForList("select id from rfq_item where rfq_id=?",Long.class,rfq));var seen=new HashSet<Long>();for(var l:body.lines()){if(!allowed.contains(l.itemId())||!seen.add(l.itemId()))throw bad("Use each item from this request once.");offer(l,r,false);}db.update("insert into rfq_pricing_work(rfq_id,sourcing_version,sourcing_draft) values (?,1,?::jsonb) on conflict(rfq_id) do update set sourcing_version=rfq_pricing_work.sourcing_version+1,sourcing_draft=excluded.sourcing_draft,updated_at=now()",rfq,encode(body));if(r.get("status").equals("submitted"))status(rfq,"submitted","in_review",p);return Map.of("version",version+1);}
 @PostMapping("/items") @Transactional
 Map<String,Object> addItem(@PathVariable long rfq,@Valid @RequestBody Item body,Principal p){var r=request(rfq,true);sourcingOnly(r);if(items(rfq).size()>=250)throw bad("A request supports up to 250 items.");String description=body.description().trim(),unit=body.unit().trim();if(body.productId()!=null){var products=db.queryForList("select name,ordering_unit from product where id=? and active=true",body.productId());if(products.isEmpty())throw bad("Choose an active catalogue product.");description=(String)products.getFirst().get("name");unit=(String)products.getFirst().get("ordering_unit");}long id=db.queryForObject("insert into rfq_item(rfq_id,description,quantity,ordering_unit,product_id,display_order) values (?,?,?,?,?,(select coalesce(max(display_order),0)+1 from rfq_item where rfq_id=?)) returning id",Long.class,rfq,description,body.quantity(),unit,body.productId(),rfq);db.update("update rfq_pricing_work set sourcing_version=sourcing_version+1 where rfq_id=?",rfq);event(rfq,p,"item_captured","Captured an item from the customer list.");return Map.of("id",id);}
 @PostMapping("/approve") @Transactional
 Map<String,Object> approve(@PathVariable long rfq,@Valid @RequestBody Approval body,Principal p){var r=request(rfq,true);var s=state(rfq);if(Set.of("approved","quoted").contains(r.get("status"))&&number(s.get("sourcing_version"))==body.version())return Map.of("approved",true);sourcingOnly(r);if(number(s.get("sourcing_version"))!=body.version())throw conflict("Save and review the latest sourcing draft.");var draft=read(s.get("sourcing_draft"),Sourcing.class);var items=items(rfq);if(items.isEmpty()||items.size()!=draft.lines().size())throw bad("Source every requested item before approval.");var snapshots=new ArrayList<Map<String,Object>>();var seen=new HashSet<Long>();for(var l:draft.lines()){var item=items.stream().filter(i->number(i.get("id"))==l.itemId()).findFirst().orElseThrow(()->bad("Invalid request item."));if(!seen.add(l.itemId()))throw bad("Duplicate item.");var o=offer(l,r,true);int quantity=l.quantity()==null?((Number)item.get("quantity")).intValue():l.quantity();BigDecimal required=BigDecimal.valueOf(quantity).multiply(l.conversion());BigDecimal packs=required.divide(decimal(o.get("units_per_pack")),0,RoundingMode.CEILING);BigDecimal total=packs.multiply(decimal(o.get("pack_price_ex_vat"))).setScale(4,RoundingMode.HALF_UP);if(total.compareTo(new BigDecimal("9999999999"))>0)throw bad("The selected purchase cost is too large.");var snap=new LinkedHashMap<String,Object>();snap.put("itemId",l.itemId());snap.put("productId",l.productId());snap.put("supplierLineId",l.supplierLineId());snap.put("conversion",l.conversion());snap.put("description",item.get("description"));snap.put("quantity",quantity);snap.put("requestedQuantity",item.get("quantity"));snap.put("unit",item.get("ordering_unit"));snap.put("source",o);snap.put("packs",packs);snap.put("extraUnits",packs.multiply(decimal(o.get("units_per_pack"))).subtract(required));snap.put("purchaseCost",total);snap.put("unitCost",total.divide(BigDecimal.valueOf(quantity),4,RoundingMode.HALF_UP));snap.put("alternativeConfirmed",l.alternativeConfirmed());snapshots.add(snap);}
  db.update("update rfq_pricing_work set approval_version=approval_version+1,approval=?::jsonb,approved_by=?,approved_at=now(),quote_draft=null,quote_version=quote_version+1 where rfq_id=?",encode(Map.of("lines",snapshots)),p.getName(),rfq);status(rfq,r.get("status").toString(),"approved",p);event(rfq,p,"sourcing_approved","Approved supplier costs. Ready for markup and transport in Approved Requests.");return Map.of("approved",true);
 }
 @PostMapping("/return") @Transactional Map<String,Object> returnSource(@PathVariable long rfq,@Valid @RequestBody Reason body,Principal p){var r=request(rfq,true);approvedOnly(r);db.update("update rfq_pricing_work set approval=null,quote_draft=null,quote_version=quote_version+1,sourcing_version=sourcing_version+1 where rfq_id=?",rfq);db.update("update quotation set status='superseded' where rfq_id=? and status in ('draft','issued')",rfq);status(rfq,r.get("status").toString(),"in_review",p);event(rfq,p,"returned_to_sourcing",body.reason().trim());return Map.of("returned",true);}
 @SuppressWarnings("unchecked") private List<Map<String,Object>> approvedLines(Map<String,Object> s){if(s.get("approval")==null)throw conflict("Sourcing approval is missing.");return (List<Map<String,Object>>)decode(s.get("approval")).get("lines");}
 private void checkQuote(QuoteDraft d,Map<String,Object> s){if(d.approvalVersion()!=number(s.get("approval_version")))throw conflict("Sourcing approval changed. Reload the request.");var approved=approvedLines(s);if(d.lines().size()!=approved.size())throw bad("Keep every approved item in the quotation. Return to sourcing to change the item list.");var seen=new HashSet<Long>();for(var l:d.lines()){var cost=approved.stream().filter(i->number(i.get("itemId"))==l.itemId()).findFirst().orElseThrow(()->bad("Use only approved request items."));if(!seen.add(l.itemId()))throw bad("Use each approved item once.");if(l.sellingPrice().compareTo(decimal(cost.get("unitCost")))<0)throw bad("A selling price is below its approved cost. Review the item.");}}
 @PostMapping("/quote") @Transactional Map<String,Object> saveQuote(@PathVariable long rfq,@Valid @RequestBody QuoteDraft body,Principal p){approvedOnly(request(rfq,true));var s=state(rfq);if(body.version()!=number(s.get("quote_version")))throw conflict("The quotation draft changed in another session. Reload it.");checkQuote(body,s);db.update("update rfq_pricing_work set quote_version=quote_version+1,quote_draft=?::jsonb,updated_at=now() where rfq_id=?",encode(body),rfq);return Map.of("version",body.version()+1);}
 private void fresh(Map<String,Object> s,Map<String,Object> r){for(var snap:approvedLines(s)){var item=db.queryForList("select quantity,ordering_unit from rfq_item where id=? and rfq_id=?",snap.get("itemId"),r.get("id"));if(item.isEmpty()||number(item.getFirst().get("quantity"))!=number(snap.get("requestedQuantity"))||!item.getFirst().get("ordering_unit").equals(snap.get("unit")))throw conflict("The requested quantity or unit changed. Return to sourcing.");var original=(Map<?,?>)snap.get("source");var l=new Source(number(snap.get("itemId")),number(snap.get("productId")),number(snap.get("supplierLineId")),((Number)snap.get("quantity")).intValue(),decimal(snap.get("conversion")),decimal(original.get("pack_price_ex_vat")),Boolean.TRUE.equals(snap.get("alternativeConfirmed")));var now=offer(l,r,true);if(number(now.get("units_per_pack"))!=number(original.get("units_per_pack"))||!now.get("match_type").equals(original.get("match_type"))||!now.get("description").equals(original.get("description"))||!now.get("pack_label").equals(original.get("pack_label")))throw conflict("An approved supplier specification changed. Return to sourcing for review.");}}
 @PostMapping("/finalise") @Transactional Map<String,Object> finalise(@PathVariable long rfq,@Valid @RequestBody Finalise body,Principal p){var r=request(rfq,true);approvedOnly(r);var existing=db.queryForList("select id,reference,rfq_id from quotation where creation_key=?",body.submissionKey());if(!existing.isEmpty()){if(number(existing.getFirst().get("rfq_id"))!=rfq)throw bad("This action key belongs to another request.");return existing.getFirst();}var s=state(rfq);if(s.get("quote_draft")==null||body.version()!=number(s.get("quote_version")))throw conflict("Save the latest quotation draft first.");var d=read(s.get("quote_draft"),QuoteDraft.class);checkQuote(d,s);fresh(s,r);if(d.validUntil().isBefore(LocalDate.now()))throw bad("Set a current quotation validity date.");int revision=db.queryForObject("select coalesce(max(revision),0)+1 from quotation where rfq_id=?",Integer.class,rfq);String ref="LQ-"+String.format("%06d",rfq)+"-R"+revision;var customer=Map.of("buyer",decode(r.get("contact_snapshot")),"requestReference",r.get("reference"),"deliveries",db.queryForList("select street,building,suburb,city,province,postal_code,contact_name,phone,required_date from rfq_delivery where rfq_id=? order by id",rfq));long id=db.queryForObject("insert into quotation(rfq_id,reference,revision,delivery_ex_vat,delivery_vat,valid_until,terms,creation_key,customer_snapshot,created_by,approval_version,draft_version) values (?,?,?,?,?,?,?,?,?::jsonb,?,?,?) returning id",Long.class,rfq,ref,revision,d.transport(),d.transport().multiply(d.vatRate()).setScale(2,RoundingMode.HALF_UP),d.validUntil(),d.terms(),body.submissionKey(),encode(customer),p.getName(),d.approvalVersion(),body.version());for(var l:d.lines()){var snap=approvedLines(s).stream().filter(i->number(i.get("itemId"))==l.itemId()).findFirst().orElseThrow();db.update("insert into quotation_item(quotation_id,rfq_id,rfq_item_id,description,quantity,ordering_unit,unit_price_ex_vat,vat_rate,supplier_cost_snapshot) values (?,?,?,?,?,?,?,?,?::jsonb)",id,rfq,l.itemId(),l.description().trim(),number(snap.get("quantity")),snap.get("unit"),l.sellingPrice(),d.vatRate(),encode(snap));}db.update("update quotation set status='superseded' where rfq_id=? and id<>? and status='draft'",rfq,id);event(rfq,p,"quotation_finalised","Finalised "+ref+" for customer preview.");return Map.of("id",id,"reference",ref);}
 @GetMapping("/quotations/{quote}") @Transactional(readOnly=true) Map<String,Object> preview(@PathVariable long rfq,@PathVariable long quote){request(rfq,false);var rows=db.queryForList("select id,reference,revision,status,created_at,valid_until,terms,delivery_ex_vat,delivery_vat,customer_snapshot,emailed_at,sent_to,approval_version,draft_version from quotation where id=? and rfq_id=?",quote,rfq);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Quotation not found.");var q=rows.getFirst();q.put("customer",q.get("customer_snapshot")==null?Map.of():decode(q.remove("customer_snapshot")));var items=db.queryForList("select description,quantity,ordering_unit,unit_price_ex_vat,vat_rate from quotation_item where quotation_id=? order by id",quote);BigDecimal subtotal=BigDecimal.ZERO,vat=BigDecimal.ZERO;for(var i:items){BigDecimal net=((BigDecimal)i.get("unit_price_ex_vat")).multiply(BigDecimal.valueOf(((Number)i.get("quantity")).longValue())).setScale(2,RoundingMode.HALF_UP);BigDecimal tax=net.multiply((BigDecimal)i.get("vat_rate")).setScale(2,RoundingMode.HALF_UP);i.put("lineTotal",net);subtotal=subtotal.add(net);vat=vat.add(tax);}vat=vat.add((BigDecimal)q.get("delivery_vat"));q.put("bankingDetails",CustomerQuotationPdf.BANKING);q.put("items",items);q.put("subtotal",subtotal);q.put("vatTotal",vat);q.put("total",subtotal.add(vat).add((BigDecimal)q.get("delivery_ex_vat")));return q;}
 @GetMapping("/quotations/{quote}/pdf") @Transactional(readOnly=true) ResponseEntity<byte[]> pdf(@PathVariable long rfq,@PathVariable long quote)throws java.io.IOException{var view=preview(rfq,quote);return ResponseEntity.ok().contentType(MediaType.APPLICATION_PDF).header("Content-Disposition",ContentDisposition.attachment().filename(view.get("reference")+".pdf").build().toString()).body(CustomerQuotationPdf.render(view));}
 private Map<String,Object> ready(long rfq,long quote,Map<String,Object> r){approvedOnly(r);var rows=db.queryForList("select * from quotation where id=? and rfq_id=? for update",quote,rfq);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Quotation not found.");var q=rows.getFirst();var s=state(rfq);if(q.get("approval_version")==null||q.get("draft_version")==null||!Set.of("draft","issued").contains(q.get("status"))||number(q.get("approval_version"))!=number(s.get("approval_version"))||number(q.get("draft_version"))!=number(s.get("quote_version")))throw conflict("The quotation changed. Finalise and preview the current version before sending.");if(((java.sql.Date)q.get("valid_until")).toLocalDate().isBefore(LocalDate.now()))throw bad("This quotation has expired.");fresh(s,r);return q;}
 @GetMapping("/quotations/{quote}/email-draft") @Transactional
 ResponseEntity<byte[]> emailDraft(@PathVariable long rfq,@PathVariable long quote)throws java.io.IOException{var r=request(rfq,true);var q=ready(rfq,quote,r);var view=preview(rfq,quote);var buyer=(Map<?,?>)((Map<?,?>)view.get("customer")).get("buyer");String recipient=Objects.toString(buyer.get("email"),"");if(!recipient.matches("[^\\r\\n<> ]+@[^\\r\\n<> ]+"))throw bad("The request needs a valid customer email address.");String ref=q.get("reference").toString(),boundary="lepetse-"+UUID.randomUUID();String text="Thank you for your enquiry. Please find quotation "+ref+" attached.\r\n\r\nKind regards,\r\nLepetse Business Enterprise and Projects (Pty) Ltd\r\nAdmin@lepetse.co.za | 084 030 3307 or 063 140 5757";String mime="To: "+recipient+"\r\nSubject: Lepetse quotation "+ref+"\r\nX-Unsent: 1\r\nMIME-Version: 1.0\r\nContent-Type: multipart/mixed; boundary=\""+boundary+"\"\r\n\r\n--"+boundary+"\r\nContent-Type: text/plain; charset=UTF-8\r\nContent-Transfer-Encoding: base64\r\n\r\n"+Base64.getMimeEncoder().encodeToString(text.getBytes(java.nio.charset.StandardCharsets.UTF_8))+"\r\n--"+boundary+"\r\nContent-Type: application/pdf\r\nContent-Disposition: attachment; filename=\""+ref+".pdf\"\r\nContent-Transfer-Encoding: base64\r\n\r\n"+Base64.getMimeEncoder().encodeToString(CustomerQuotationPdf.render(view))+"\r\n--"+boundary+"--\r\n";return ResponseEntity.ok().contentType(MediaType.parseMediaType("message/rfc822")).header("Content-Disposition",ContentDisposition.attachment().filename(ref+".eml").build().toString()).body(mime.getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 @PostMapping("/quotations/{quote}/record-sent") @Transactional
 Map<String,Object> sent(@PathVariable long rfq,@PathVariable long quote,@Valid @RequestBody Sent body,Principal p){var r=request(rfq,true);var q=ready(rfq,quote,r);String expected=Objects.toString(decode(r.get("contact_snapshot")).get("email"),"");if(!body.recipient().equalsIgnoreCase(expected))throw bad("Use the original requester's email. Correct the customer record before changing the recipient.");if(q.get("status").equals("issued"))return Map.of("recorded",true);db.update("update quotation set status='superseded' where rfq_id=? and status='issued'",rfq);db.update("update quotation set status='issued',issued_at=now(),emailed_at=now(),sent_to=? where id=?",body.recipient(),quote);status(rfq,r.get("status").toString(),"quoted",p);event(rfq,p,"sent_recorded","Recorded "+q.get("reference")+" as emailed to "+body.recipient()+" outside the dashboard.");return Map.of("recorded",true);}
}
